/* GENERATED by scripts/build-kosmic-sky.mjs from the landing page's
   Sky.astro: the live aurora, a WebGL shader drawn on the canvas in
   components/kosmic-sky.html. The drawn sheets behind it stand in
   until it runs and wherever it cannot. Rerun the script rather than
   editing here. */
(() => {

    /* The live aurora. Where WebGL is to be had, the display is drawn
       fresh every frame by a fragment shader, and the sheets above are
       hidden: a drawn sheet can only tilt and fade, while this one
       ripples, streams, flares, and re-forms. The shader works in polar
       coordinates about the zenith the rays point at, high over the top
       of the window: a ray is a line of constant angle, and a curtain is
       a hem radius, a presence, and a set of striations, each a function
       of the angle and of time. Bending the angle by a noise that varies
       with the radius curves the rays, and moving that noise in time
       sends waves along the curtains. The sheets stay for browsers
       without WebGL, and for the moment before the first frame. */
    const vert = `
attribute vec2 p;
void main() { gl_Position = vec4(p, 0.0, 1.0); }`;

    const frag = `
precision highp float;
uniform vec2 u_res;
uniform float u_time;
uniform float u_fade;

/* Fringe, foot, middle, and tip of a ray: the same colours as the drawn
   sheets, Nord's Frost and purple with brighter greens. */
const vec3 GREEN = vec3(0.498, 0.890, 0.631);
const vec3 TEAL = vec3(0.435, 0.812, 0.753);
const vec3 FROST = vec3(0.533, 0.753, 0.816);
const vec3 VIOLET = vec3(0.706, 0.557, 0.678);
const vec3 LILAC = vec3(0.647, 0.588, 0.863);
const vec3 PINK = vec3(0.941, 0.639, 0.769);

float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 3; i++) {
        v += a * noise(p);
        p = p * 2.03 + 17.1;
        a *= 0.5;
    }
    return v / 0.875;
}

/* One curtain, at a point (th, r) of the sky: angle from straight down
   out of the zenith, and distance from it. foot is the hem's radius,
   height how far up the rays reach, slope how the hem runs across the
   sky, hue how far the tips lean from violet (0) to lilac and frost (1).

   The rays are all but straight, as rays are: they run along the field
   lines. The curtain's sweep is in its hem, which folds and wanders, so
   the sheet still hooks and scallops without the rays bending like
   smoke. The hem is one crisp edge, with the brightest light just above
   it; everything else is soft. */
vec3 curtain(float th, float r, float t, float seed, float foot, float height,
        float slope, float hue) {
    // Each run of rays has a slight lean of its own, straight but not
    // quite at the zenith, so the fan is not ruled from one point; and a
    // slow broad drift, nothing like a bend.
    float tilt = 0.14 * (noise(vec2(th * 4.0 + seed * 3.0, t * 0.02)) - 0.5);
    float a = th + tilt * (r - foot) / height
            + 0.04 * (fbm(vec2(th * 1.3 + seed, r * 0.8 - t * 0.05)) - 0.5);
    // Where the curtain is: groups of rays with dark sky between them,
    // and pulses of brightness running along it.
    float presence = smoothstep(0.42, 0.7, fbm(vec2(a * 5.0 + seed * 7.0, t * 0.03)));
    presence *= 0.5 + 0.5 * noise(vec2(a * 9.0 - t * 0.2, seed));
    // The striations, which the hem is ragged by too.
    float n1 = noise(vec2(a * 75.0 + t * 0.25, seed * 5.0));
    float n2 = noise(vec2(a * 200.0 - t * 0.4, seed * 9.0));
    float n3 = noise(vec2(a * 420.0 + t * 0.3, seed * 13.0));
    // The hem: it wanders across the sky and folds, with waves running
    // along it, hangs lower where the curtain is thick, and is ragged
    // from ray to ray.
    float f = foot + slope * a
            + 0.42 * (fbm(vec2(a * 3.0 + seed, t * 0.07 + seed)) - 0.5)
            + 0.10 * (noise(vec2(a * 6.0 - t * 0.35, seed + 2.0)) - 0.5)
            + 0.2 * presence
            + 0.1 * (noise(vec2(a * 40.0 + t * 0.2, seed * 3.0)) - 0.5)
            + 0.04 * (n1 - 0.5);
    float reach = 0.6 + 0.8 * noise(vec2(a * 6.0 + seed, t * 0.07));
    float h = height * reach;
    // Up the ray: 0 at the hem, 1 at its full reach.
    float u = (f - r) / h;
    float up = max(u, 0.0);
    // Striations: most faint, a few sharp and bright, drifting along the
    // curtain, with fine grain between.
    float s = (pow(n1, 5.0) * 3.0 + 0.15) * (0.6 + 0.8 * n2) * (0.85 + 0.3 * n3);
    // One edge at the hem, ragged from ray to ray, the brightest light
    // just above it, then a long fade to the tip.
    float prof = smoothstep(-0.08, 0.06, u) * (exp(-up * 2.2) + 0.6 * exp(-up * 10.0));
    // Pulses run along the curtain, and now and then a flame runs up a
    // ray, fast.
    prof *= 0.65 + 0.5 * noise(vec2(a * 14.0 - t * 0.6, u * 1.5 + seed));
    prof *= 1.0 + 0.4 * pow(noise(vec2(a * 20.0 + seed, u * 1.2 - t * 1.2)), 3.0);
    float I = presence * s * prof;
    // The body of the sheet, a soft glow between the rays, thickest low
    // down, and a little airglow about the whole curtain.
    I += presence * 0.1 * smoothstep(-0.1, 0.1, u) * exp(-up * 2.5)
        * (0.5 + 0.5 * noise(vec2(a * 25.0, u * 3.0 - t * 0.15)));
    I += presence * 0.04 * smoothstep(-0.2, 0.15, u) * exp(-up * 1.5);
    // The brightest cores stay green rather than burning to white.
    I /= 1.0 + 0.35 * I;
    // Oxygen green, through and through; a cooler cast toward the
    // middle, and violet only on the tops of the tallest rays.
    vec3 col = mix(GREEN, TEAL, 0.35 * smoothstep(0.2, 0.7, u));
    float tall = smoothstep(0.9, 1.3, reach);
    col = mix(col, mix(VIOLET, LILAC, hue), tall * smoothstep(0.55, 1.1, u));
    col = mix(col, FROST, 0.25 * hue * smoothstep(0.3, 0.8, u));
    // The pink lower fringe of a bright, low curtain.
    col = mix(col, PINK, smoothstep(0.08, -0.03, u) * clamp(I * 1.2 - 0.4, 0.0, 1.0));
    return col * I * 3.4;
}

void main() {
    vec2 uv = gl_FragCoord.xy / u_res;
    float aspect = u_res.x / u_res.y;
    // x across in units of the height, y down from the top.
    vec2 p = vec2(uv.x * aspect, 1.0 - uv.y);
    // The zenith: a little right of centre, well over the top.
    vec2 z = vec2(0.56 * aspect, -1.1);
    vec2 d = p - z;
    float r = length(d);
    float th = atan(d.x, d.y);
    float t = u_time;
    if (u_fade <= 0.0) {
        gl_FragColor = vec4(0.0);
        return;
    }
    // The display swells and subsides over minutes, and never quite goes.
    float env = 0.5 + 0.5 * smoothstep(0.25, 0.8, fbm(vec2(t * 0.02, 7.7)));
    vec3 c = vec3(0.0);
    // Each curtain is worked out only where it shows: a curtain is most
    // of the cost of a pixel, and most pixels see one or two of them.
    // The main curtain, tall and bright, over the right, and a bright pair
    // in the middle, with their hems low in the window: on the landing
    // page the cards cover that ground, and the hems peek out from behind
    // them. Each curtain drifts a little across the sky.
    float wMain = smoothstep(-0.1, 0.2, th + 0.08 * sin(t * 0.017 + 2.0));
    if (wMain > 0.0) c += curtain(th, r, t, 2.0, 2.1, 0.75, 0.1, 0.3) * wMain;
    float m = th + 0.06 * sin(t * 0.025 + 4.0);
    float wMid = exp(-m * m * 60.0);
    if (wMid > 0.003) c += curtain(th, r, t, 3.0, 2.05, 0.8, -0.1, 0.1) * wMid;
    // Later, a short curtain over the left whose hem hangs in plain view,
    // above the bottom third of the window. It comes in after half a
    // minute or so and then comes and goes, so it is an event in the
    // display rather than a fixture beside it. Its rays are short, and
    // stay clear of the logo in the corner.
    float lx = uv.x + 0.03 * sin(t * 0.023 + 1.0);
    float late = smoothstep(25.0, 40.0, t)
        * smoothstep(-0.2, 0.5, sin(t * 0.045 - 1.4));
    float wLeft = late * smoothstep(0.03, 0.13, lx) * smoothstep(0.42, 0.26, lx);
    if (wLeft > 0.0) c += curtain(th, r, t, 4.0, 1.42, 0.36, -0.5, 0.4) * 1.1 * wLeft;
    c *= env * u_fade;
    // Tone-mapped on the brightest channel, and the colour scaled with
    // it, so a bright core stays green rather than burning to white.
    float l = max(c.r, max(c.g, c.b));
    float m2 = 1.0 - exp(-l * 1.2);
    vec3 o = l > 0.0 ? c * (m2 / l) : c;
    gl_FragColor = vec4(o, m2);
}`;

    /* The display is drawn only while its root has a size. The app that
       shares this script (law's Kosmic theme, built from this file by its
       scripts/build-kosmic-sky.mjs) shows the sky under one theme of
       several and hides it under the others, and a hidden canvas should
       cost nothing: a ResizeObserver starts the display, sizes it, and
       stops it, and no WebGL context is made until the sky is seen. */
    const root = document.querySelector             ("[data-aurora]");
    const canvas = root?.querySelector("canvas");
    const still = matchMedia("(prefers-reduced-motion: reduce)").matches;

    if (root && canvas && !still) {




        // null until first seen; false once WebGL has failed or been lost,
        // after which the drawn sheets stand in for good.
        let display                         = null;

        const setUp = ()                  => {
            const gl = canvas.getContext("webgl", {
                alpha: true,
                premultipliedAlpha: true,
                antialias: false,
                depth: false,
                stencil: false,
                powerPreference: "low-power",
            });
            if (!gl) return false;
            const shader = (type        , src        ) => {
                const s = gl.createShader(type) ;
                gl.shaderSource(s, src);
                gl.compileShader(s);
                if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
                    console.error("aurora:", gl.getShaderInfoLog(s));
                }
                return s;
            };
            const prog = gl.createProgram() ;
            gl.attachShader(prog, shader(gl.VERTEX_SHADER, vert));
            gl.attachShader(prog, shader(gl.FRAGMENT_SHADER, frag));
            gl.linkProgram(prog);
            if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
                console.error("aurora:", gl.getProgramInfoLog(prog));
                return false;
            }
            gl.useProgram(prog);
            gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
            gl.bufferData(
                gl.ARRAY_BUFFER,
                new Float32Array([-1, -1, 3, -1, -1, 3]),
                gl.STATIC_DRAW,
            );
            const p = gl.getAttribLocation(prog, "p");
            gl.enableVertexAttribArray(p);
            gl.vertexAttribPointer(p, 2, gl.FLOAT, false, 0, 0);
            const uRes = gl.getUniformLocation(prog, "u_res");
            const uTime = gl.getUniformLocation(prog, "u_time");
            const uFade = gl.getUniformLocation(prog, "u_fade");

            /* The display is soft, so it is drawn at about half the
               window's pixels, and never more than 960 across, and the
               browser scales it up. quality comes down from 1 if the
               device cannot keep up (see frame). */
            let quality = 1;
            const size = () => {
                const w = root.clientWidth;
                const h = root.clientHeight;
                const scale =
                    quality *
                    Math.min(0.5 * Math.min(devicePixelRatio || 1, 2), 960 / w);
                const cw = Math.max(1, Math.round(w * scale));
                const ch = Math.max(1, Math.round(h * scale));
                // Setting a canvas's size clears it, so leave it be
                // unless it has changed.
                if (cw === canvas.width && ch === canvas.height) return;
                canvas.width = cw;
                canvas.height = ch;
                gl.viewport(0, 0, cw, ch);
                gl.uniform2f(uRes, cw, ch);
            };

            /* Thirty frames a second is plenty for something this slow,
               and half the work of sixty. The frames keep to a steady
               beat, so that on a 60Hz or 120Hz screen every one lasts
               the same number of refreshes. The clock reads as though
               it started SET_UP_AT before the display was made: on the
               landing page that is the page's load, and the display
               comes up once the title has settled (its focus animation
               is done by 1s, the stars by 1.4s), over a few seconds;
               until then nothing is drawn. In the app, where the sky
               may first be seen long after load, it still fades in.

               If the frames keep coming late, the device is not keeping
               up: the display is drawn smaller, a step at a time, and
               if that is not enough it gives way to the drawn sheets,
               which cost next to nothing. */
            const STEP = 1000 / 30;
            const FADE_IN = 2.5;
            const start = performance.now() - SET_UP_AT;
            let last = -1e9;
            let running = false;
            let handle = 0;
            let drawn = 0;
            let late = 0;
            const frame = (now        ) => {
                if (!running) return;
                handle = requestAnimationFrame(frame);
                if (now - last < STEP - 2) return;
                const gap = now - last;
                // Back on the beat, unless a long gap (a frame dropped,
                // or the tab away) means starting it afresh.
                last = gap > 2 * STEP ? now : last + STEP;
                const t = (now - start) / 1000;
                if (t < FADE_IN) return;
                const fade = Math.min(1, (t - FADE_IN) / 3.5);
                gl.uniform1f(uTime, t % 100000);
                gl.uniform1f(uFade, fade * fade * (3 - 2 * fade));
                gl.drawArrays(gl.TRIANGLES, 0, 3);

                if (gap > 1.6 * STEP && gap < 500) late++;
                if (++drawn < 60) return;
                if (late > 9) {
                    if (quality > 0.5) {
                        quality *= 0.8;
                        size();
                    } else {
                        run(false);
                        display = false;
                    }
                }
                drawn = late = 0;
            };
            const run = (on         ) => {
                if (on === running) return;
                running = on;
                root.classList.toggle("live", on);
                if (on) handle = requestAnimationFrame(frame);
                else cancelAnimationFrame(handle);
            };

            // One frame, at once and out of sight, so that the GPU has
            // the shader ready before the display has to move.
            size();
            gl.uniform1f(uFade, 0);
            gl.drawArrays(gl.TRIANGLES, 0, 3);

            canvas.addEventListener("webglcontextlost", (e) => {
                // Back to the drawn sheets rather than a blank sky.
                e.preventDefault();
                run(false);
                display = false;
            });
            return { size, run };
        };

        /* Making the display, which compiles the shader, waits until the
           title's own animations are done, so as not to cost them a
           frame. */
        const SET_UP_AT = 1500;
        let waiting = false;
        const sync = () => {
            const shown = root.clientWidth > 0 && root.clientHeight > 0;
            if (shown && display === null) {
                const wait = SET_UP_AT - performance.now();
                if (wait > 0) {
                    if (!waiting) {
                        waiting = true;
                        setTimeout(() => {
                            waiting = false;
                            sync();
                        }, wait);
                    }
                    return;
                }
                display = setUp();
            }
            if (!display) return;
            if (shown) display.size();
            display.run(shown);
        };
        new ResizeObserver(sync).observe(root);
    }

})();
